    public static final String VERSION="SRPP_REPORT_CALCULATIONS_V1";
    public static final List<String> MODULE_IDS=List.of("ASSET_RECONCILIATION","ALLOCATION_GAP","FUNDING_CAPACITY","CASH_INCOME","PAYROLL_CASHFLOW","BOND_D130_D195","DIVIDEND_TOPUP","CORE_SELL_GUARD","STRATEGIC_BUY_GATES","GLOBAL_EQUITY_PACE","ROTATION_AND_REGIME_CAPACITY","SHORT_TERM_AND_US_TACTICAL");
