    public static ObjectNode coreTiming(JsonNode body,JsonNode state,LocalDate date,JsonNode policy){if(state==null||!state.isObject()||!state.path("policy_sha256").asText().equals(SrppJcs.sha256Hex(numericJson(policy)))||!state.path("stock_code").asText().equals(body.path("symbol").asText())||!"台股".equals(state.path("market").asText())||state.path("evidence_sha256").asText().isBlank())throw new Gap("WATCH_STATE_UNVERIFIED");JsonNode q=body.path("quote"),radar=body.path("radar").path("stock"),ind=radar.path("extendedIndicators");if(!"LIVE".equals(q.path("quoteStatus").asText())||!date.toString().equals(q.path("tradingDate").asText())||!radar.path("dataComplete").asBoolean())throw new Gap("EXACT_RADAR_UNVERIFIED");BigDecimal currentHigh=required(q.get("highPrice")),bid=num(body.path("book").path("levels").path(0).get("bidPrice"));if(!positive(bid))throw new Gap("SELL_BID_UNVERIFIED");LocalDate basis=LocalDate.parse(state.path("basis_date").asText()),highDate=LocalDate.parse(state.path("high_date").asText()),armed=LocalDate.parse(state.path("armed_date").asText());if(armed.isAfter(highDate)||highDate.isAfter(basis)||basis.isAfter(date))throw new Gap("WATCH_STATE_UNVERIFIED");Set<String>non=strings(policy.path("non_distributing_symbols"));Map<LocalDate,BigDecimal>events=events(body,date,non);BigDecimal high=required(state.get("high_water")).subtract(cashAfter(events,basis));Map<String,JsonNode>daily=rows(body.path("daily"),"tradingDate");List<String>sessions=new ArrayList<>(stringsOrdered(body.path("completedSessions")));if(!body.path("calendarVerified").asBoolean()||sessions.size()<policy.path("kd_corporate_action_lookback").asInt())throw new Gap("COMPLETED_KD_OR_OHLC_UNVERIFIED");for(String day:sessions){LocalDate d=LocalDate.parse(day);if(d.isBefore(basis))continue;JsonNode row=daily.get(day);if(row==null||!row.path("trusted").asBoolean())throw new Gap("COMPLETED_KD_OR_OHLC_UNVERIFIED");BigDecimal candidate=required(row.get("highPrice")).subtract(cashAfter(events,d));if(candidate.compareTo(high)>0){high=candidate;highDate=d;}}if(currentHigh.compareTo(high)>0){high=currentHigh;highDate=date;}if(high.signum()<=0)throw new Gap("WATCH_PRICE_BASIS_UNVERIFIED");List<String>confirmation=sessions.subList(sessions.size()-3,sessions.size());Map<String,JsonNode>byInd=rows(body.path("indicators"),"tradingDate");BigDecimal[]ks=new BigDecimal[3],ds=new BigDecimal[3];for(int i=0;i<3;i++){JsonNode row=byInd.get(confirmation.get(i));if(row==null)throw new Gap("COMPLETED_KD_OR_OHLC_UNVERIFIED");ks[i]=domain(row.get("k"),ZERO,HUNDRED);ds[i]=domain(row.get("d"),ZERO,HUNDRED);}LocalDate lookback=LocalDate.parse(sessions.get(sessions.size()-policy.path("kd_corporate_action_lookback").asInt()));if(events.entrySet().stream().anyMatch(v->v.getKey().isAfter(lookback)&&v.getValue().signum()>0))throw new Gap("KD_CORPORATE_ACTION_BASIS_UNVERIFIED");boolean after=LocalDate.parse(confirmation.get(1)).isAfter(highDate),weak=ks[0].compareTo(ks[1])>0&&ks[1].compareTo(ks[2])>0&&ks[2].compareTo(ds[2])<0&&ds[2].compareTo(ds[1])<0&&domain(radar.get("kValue"),ZERO,HUNDRED).compareTo(domain(radar.get("dValue"),ZERO,HUNDRED))<0;BigDecimal pullback=div(high.subtract(bid),high);boolean compatible=strings(policy.path("compatible_sell_actions")).contains(radar.path("action").asText())&&strings(policy.path("compatible_sell_actions")).contains(radar.path("candidateAction").asText());String reason=!compatible?"RADAR_SELL_CONFLICT":!after||!weak?"WAIT_CONFIRMED_TREND_REVERSAL":pullback.compareTo(required(policy.get("pullback_fraction")))<0?"HIGH_WATER_PULLBACK_NOT_MET":"CONFIRMED_REVERSAL_AND_PULLBACK";ObjectNode out=F.objectNode();out.put("highWater",dec(high));out.put("pullbackPct",dec(pullback.multiply(HUNDRED)));out.put("overheatHits",overheatRadar(radar,ind));out.put("trendReversal",after&&weak);out.put("timingPass",reason.equals("CONFIRMED_REVERSAL_AND_PULLBACK"));out.put("reason",reason);return out;}
    /** D175 same-row identity and source age; volume is converted exactly, never floored. */
    public static String quoteFreshness(JsonNode body,DecisionInputCapturePort.Frozen f,JsonNode model,boolean finalStage){
        JsonNode q=body.path("quote"),p=model.path("execution_policy").path("bond_trade_price_policy").path("quote_freshness_policy");
        if(!body.path("symbol").asText().equals(q.path("stockCode").asText())||!body.path("market").asText().equals(q.path("market").asText())||!f.facts().date().toString().equals(q.path("tradingDate").asText())||!"LIVE".equals(q.path("quoteStatus").asText())||q.path("closed").isMissingNode()||!q.path("closed").isBoolean()||q.path("closed").asBoolean()||q.path("source").asText().isBlank()||!positive(num(q.get("price"))))throw new Gap("LIVE_QUOTE_IDENTITY_UNVERIFIED");
        Instant updated=instant(q.path("updatedAt"));Instant asOf=f.facts().capturedAt();if(updated.isAfter(asOf)||!updated.atZone(ZoneId.of("Asia/Taipei")).toLocalDate().equals(f.facts().date()))throw new Gap("LIVE_QUOTE_TIMESTAMP_UNVERIFIED");
        BigDecimal lots=num(q.get("volume"));if(lots!=null){if("SHARES".equals(body.path("volumeUnit").asText()))lots=lots.divide(THOUSAND);else if(!"LOTS".equals(body.path("volumeUnit").asText()))lots=null;if(lots!=null&&lots.stripTrailingZeros().scale()>0)lots=null;}
        BigDecimal previous=num(q.get("previousClose"));String status="LIVE_QUOTE_FRESH";int minutes=p.path(finalStage?"default_final_limit_max_minutes":"default_acquisition_max_minutes").asInt();
        if("09:05".equals(f.facts().slot())&&positive(lots)&&lots.compareTo(required(p.get("early_volume_below_lots")))<0&&positive(previous)&&required(q.get("price")).compareTo(previous)!=0)return "EARLY_TRADED_PRICE_NO_AGE_LIMIT";
        if("12:00".equals(f.facts().slot())&&positive(lots)){if(lots.compareTo(THOUSAND)<=0){minutes=p.path("midday_volume_at_most_1000_max_minutes").asInt();status="MIDDAY_VOLUME_LE_1000_20M";}else if(lots.compareTo(new BigDecimal("1500"))<=0){minutes=p.path("midday_volume_1001_through_1500_max_minutes").asInt();status="MIDDAY_VOLUME_1001_1500_15M";}}
        if(minutes<=0||Duration.between(updated,asOf).compareTo(Duration.ofMinutes(minutes))>0)throw new Gap("LIVE_QUOTE_STALE");return status;
    }
    private static Instant instant(JsonNode node){try{return Instant.parse(node.asText());}catch(DateTimeException absent){try{return OffsetDateTime.parse(node.asText()).toInstant();}catch(DateTimeException local){try{return LocalDateTime.parse(node.asText()).atZone(ZoneId.of("Asia/Taipei")).toInstant();}catch(DateTimeException invalid){throw new Gap("SOURCE_TIMESTAMP_UNVERIFIED");}}}}
