    private static List<Row> adjustedWindow(JsonNode body,LocalDate date,int count,Set<String>non,String field){if(count<1||!body.path("calendarVerified").asBoolean())throw new Gap("COMPLETED_CLOSES_UNVERIFIED");List<String>sessions=stringsOrdered(body.path("completedSessions"));if(sessions.size()<count)throw new Gap("COMPLETED_CLOSES_UNVERIFIED");List<String>wanted=sessions.subList(sessions.size()-count,sessions.size());Map<String,JsonNode>byDate=rows(body.path("daily"),"tradingDate");Map<LocalDate,BigDecimal>events=events(body,date,non);List<Row>out=new ArrayList<>();for(String day:wanted){LocalDate d=LocalDate.parse(day);JsonNode row=byDate.get(day);if(!d.isBefore(date)||row==null||!row.path("trusted").asBoolean())throw new Gap("COMPLETED_CLOSES_UNVERIFIED");BigDecimal value=required(row.get(field)).subtract(cashAfter(events,d));if(value.signum()<=0)throw new Gap("ADJUSTED_CLOSE_NONPOSITIVE");out.add(new Row(d,value));}return out;}
    private static List<Row> adjustedAvailable(JsonNode body,LocalDate date,int count,Set<String>non,String field){List<String>sessions=stringsOrdered(body.path("completedSessions"));if(sessions.isEmpty())throw new Gap("TRADING_CALENDAR_UNVERIFIED");Map<String,JsonNode>byDate=rows(body.path("daily"),"tradingDate");Map<LocalDate,BigDecimal>events=events(body,date,non);List<Row>out=new ArrayList<>();for(String day:sessions.subList(Math.max(0,sessions.size()-count),sessions.size())){JsonNode row=byDate.get(day);if(row==null)continue;if(!row.path("trusted").asBoolean())throw new Gap("PRICE_HISTORY_UNVERIFIED");BigDecimal value=num(row.get(field));if(value!=null)out.add(new Row(LocalDate.parse(day),value.subtract(cashAfter(events,LocalDate.parse(day)))));}return out;}
    private static Map<LocalDate,BigDecimal> events(JsonNode body,LocalDate date,Set<String>non){Map<LocalDate,BigDecimal>out=new TreeMap<>();if(non.contains(body.path("symbol").asText()))return out;JsonNode events=body.path("dividends");if(!events.isArray()||events.isEmpty())throw new Gap("DIVIDEND_HISTORY_UNVERIFIED");for(JsonNode row:events){if(!body.path("symbol").asText().equals(row.path("stockCode").asText())||!body.path("market").asText().equals(row.path("market").asText())||row.path("source").asText().isBlank())throw new Gap("DIVIDEND_HISTORY_UNVERIFIED");String ex=row.path("exDividendDate").asText();if(ex.isBlank())throw new Gap("DIVIDEND_HISTORY_UNVERIFIED");LocalDate day=LocalDate.parse(ex);BigDecimal cash=required(row.get("cashDividend")),stock=num(row.get("stockDividend"));if(cash.signum()<0||stock!=null&&stock.signum()!=0||!row.path("exRightsDate").isMissingNode()&&!row.path("exRightsDate").isNull())throw new Gap("STOCK_DIVIDEND_ADJUSTMENT_UNSUPPORTED");if(!day.isAfter(date)){BigDecimal old=out.putIfAbsent(day,cash);if(old!=null&&old.compareTo(cash)!=0)throw new Gap("DISTRIBUTION_CONFLICT");}}return out;}
