    static final class M {final ObjectNode node=F.objectNode();final ArrayNode facts,legs,ranking,receipts;final SortedSet<String>missing=new TreeSet<>(),refs=new TreeSet<>();M(String id,String scope,List<String>sources){node.put("moduleId",id);node.put("formulaVersion",VERSION);node.putArray("scope").add(scope);ObjectNode data=node.putObject("data");facts=data.putArray("facts");legs=data.putArray("legs");ranking=data.putArray("ranking");data.put("eventEvidenceIntegrationStatus","NOT_BOUND");receipts=node.putArray("receipts");refs.addAll(sources);}void fact(String name,String subject,BigDecimal value,String unit){facts.add(SrppReportModuleCalculator.fact(name,subject,value,unit));if(value==null)missing(name+(subject==null?"":":"+subject));}void missing(String reason){missing.add(reason);}void receipt(String rule,String status,String reason,List<String>sources){receipts.add(SrppReportModuleCalculator.receipt(rule,status,reason,sources));refs.addAll(sources);}void unimplemented(String scope,List<String>sources){missing("CALCULATOR_SCOPE_NOT_VERIFIED:"+scope);receipt(scope,"NOT_EVALUATED","CALCULATOR_SCOPE_NOT_VERIFIED",sources);}ObjectNode notEvaluated(String reason){node.put("status","NOT_EVALUATED");node.putArray("missing");node.putArray("reasonCodes").add(reason);ArrayNode in=node.putArray("inputRefs");refs.forEach(in::add);return node;}ObjectNode done(){boolean any=java.util.stream.StreamSupport.stream(facts.spliterator(),false).anyMatch(n->!n.path("value").isNull())||!legs.isEmpty();node.put("status",missing.isEmpty()?"COMPLETE":any?"PARTIAL":"UNAVAILABLE");ArrayNode ms=node.putArray("missing"),rs=node.putArray("reasonCodes"),in=node.putArray("inputRefs");missing.forEach(ms::add);missing.forEach(rs::add);refs.forEach(in::add);return node;}}
